function parseConventional(msg){
  var re=/^([a-z]+)(\(([^)]*)\))?(!)?:\s*(.*)/;
  var m=msg.match(re);
  if(!m) return { valid:false, raw:msg };
  var description=m[5];
  var body='';
  var nl=msg.indexOf('\n');
  if(nl>=0) body=msg.slice(nl+1).replace(/^\s+/,'').replace(/\s+$/,'');
  return {
    valid:true,
    type:m[1],
    scope:m[3]||null,
    breaking: !!m[4],
    description: description,
    body: body
  };
}
var EXPORTS = { parseConventional:parseConventional };


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ConventionalForgePure = EXPORTS; }
